from apps.organizations.choices import DocumentCategory


def folders_from_categories(apps, schema_editor):
    """One folder per category an organization uses; its documents move in."""
    Document = apps.get_model("organizations", "OrganizationDocument")
    Folder = apps.get_model("organizations", "KnowledgeFolder")
    labels = dict(DocumentCategory.choices)
    pairs = (
        Document.objects.filter(folder__isnull=True)
        .values_list("organization_id", "category")
        .distinct()
    )
    for organization_id, category in pairs:
        folder, _ = Folder.objects.get_or_create(
            organization_id=organization_id, name=labels.get(category, "Other")
        )
        Document.objects.filter(
            organization_id=organization_id, category=category, folder__isnull=True
        ).update(folder=folder)


